// npm run manifests [-- --check]
// Reads every games/<slug>/game.json, validates it, and writes what is generated from it:
//   apps/site/src/data/games.generated.ts  the website's game registry
//   README.md (between the GAMES markers)  the game showcase table
//   llms.txt and apps/site/public/llms.txt  the summary for AI assistants
// --check fails (for CI) when any generated file is out of date instead of writing it.
import { existsSync,readFileSync,writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { ageText,readManifests,validateManifest,type Manifest } from './lib/manifest';
import { root,site } from './lib/repo';

const SITE = 'https://aikids.games';
const REPO = 'https://github.com/msoyaph/AI-Kids-Games';
const check = process.argv.includes('--check');
const manifests = readManifests();
const errors = manifests.flatMap(m => validateManifest(m));
if (errors.length) { console.error(`Game manifests are invalid:\n${errors.map(error => `  • ${error}`).join('\n')}`); process.exit(1); }
// Site order: site.order first (lower first), then featured, newest, and title (stable for diffs).
manifests.sort((a,b) => (a.site.order ?? 1e9)-(b.site.order ?? 1e9) || Number(b.site.featured)-Number(a.site.featured) || b.site.releaseDate.localeCompare(a.site.releaseDate) || a.title.localeCompare(b.title));

function registry(list: Manifest[]) {
  const entries = list.map(m => ({
    slug: m.slug,title: m.title,tagline: m.tagline,description: m.shortDescription,version: m.version,
    categories: m.genres,tags: m.tags,keywords: m.keywords,ageGuidance: ageText(m),minAge: m.minAge,contentNotes: m.contentNotes,
    estimatedPlayTime: m.playTime,quickStart: m.controls.quickStart,controls: { types: m.controls.types,howToPlay: m.controls.howToPlay },
    supportedDevices: m.devices,orientation: m.orientation,requirements: m.requirements ?? [],
    coverLayers: m.site.coverLayers,releaseDate: m.site.releaseDate,featured: m.site.featured,accentColor: m.site.accentColor,status: m.site.status
  }));
  return `// Generated by \`npm run manifests\` from games/<slug>/game.json. Do not edit by hand.\nimport type { Game } from './games';\n\nexport const generatedGames: Game[] = ${JSON.stringify(entries,null,2)};\n`;
}

const cell = (text: string) => text.replace(/\|/g,'\\|');
function table(list: Manifest[]) {
  const rows = list.map(m => `| <a href="${SITE}/game/${m.slug}"><img src="apps/site/public/media/${m.slug}/readme.webp" width="280" alt="${m.title}: gameplay preview"></a> | **[${m.title}](${SITE}/game/${m.slug})**<br>${cell(m.tagline)} ${cell(m.shortDescription)} | ${ageText(m)} | ${m.genres.join(', ')} | [Play](${SITE}/play/${m.slug}) · [Source](games/${m.slug}) |`);
  return ['<!-- GAMES:START (generated by npm run manifests) -->','| | Game | Ages | Genre | |','|---|---|---|---|---|',...rows,'<!-- GAMES:END -->'].join('\n');
}

function llms(list: Manifest[]) {
  return `# Ai Kids Games

> Free, open-source browser games for kids: kart racing, farming, tower defense, space adventures and more. No ads, no subscriptions, no sign-ups, no tracking. Every game runs offline from a single HTML file.

Ai Kids Games (${SITE}) is a website of original games made for kids, plus the open-source monorepo they are built in (${REPO}). The site and the games collect no data: there are no accounts, ads, analytics, chat or requests to other websites, and game progress stays in the player's browser. Each game is a single self-contained HTML file that also works offline.

## Games

${list.map(m => `- [${m.title}](${SITE}/game/${m.slug}): ${m.shortDescription} ${ageText(m)}. ${m.genres.join(', ')}. Plays on ${m.devices.join(', ').toLowerCase()} with ${m.controls.types.join(', ').toLowerCase()}. Play time: ${m.playTime}. [Play](${SITE}/play/${m.slug}) · [Source](${REPO}/tree/main/games/${m.slug})`).join('\n')}

## For parents

- [For parents](${SITE}/parents): age guidance, content notes and controls for every game.
- [Privacy](${SITE}/privacy): no accounts, ads, analytics or tracking; saves stay on the device.

## Build your own

- [Create a game](${REPO}/blob/main/docs/CREATE-A-GAME.md): the game contract and the starter template.
- [Example briefs](${REPO}/tree/main/docs/prompts): the prompts the games were built from with Claude Code.
- [List your game](${SITE}/list-your-game): listing on aikids.games is coming soon; requests go through GitHub.
`;
}

const outputs: [string,string][] = [[resolve(site,'src/data/games.generated.ts'),registry(manifests)],[resolve(root,'llms.txt'),llms(manifests)],[resolve(site,'public/llms.txt'),llms(manifests)]];
const readme = resolve(root,'README.md');
if (existsSync(readme)) {
  const current = readFileSync(readme,'utf8');
  const next = current.replace(/<!-- GAMES:START[\s\S]*?<!-- GAMES:END -->/,table(manifests));
  outputs.push([readme,next]);
}
const stale = outputs.filter(([file,text]) => !existsSync(file) || readFileSync(file,'utf8') !== text).map(([file]) => file.slice(root.length));
if (check) {
  if (stale.length) { console.error(`Generated files are out of date: ${stale.join(', ')}. Run npm run manifests.`); process.exit(1); }
  console.log(`Manifests valid and generated files up to date (${manifests.length} games).`);
} else {
  for (const [file,text] of outputs) writeFileSync(file,text);
  console.log(`${manifests.length} manifests valid. ${stale.length ? `Updated ${stale.join(', ')}.` : 'Nothing changed.'}`);
}
